    C1 as cmte_id,
    C2 as cmte_nm,
    C3 as tres_nm,
    C4 as cmte_st1,
    C5 as cmte_st2,
    C6 as cmte_city,
    C7 as cmte_st,
    C8 as cmte_zip,
    C9 as cmte_dsgn,
    C10 as cmte_tp,
    C11 as cmte_pty_affiliation,
    C12 as cmte_filing_freq,
    C13 as org_tp,
    C14 as connected_org_nm,
    C15 as cand_id
